//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay for a retry number, where the first retry is number 0.
    pub fn delay_for_retry(&self, retry_number: u32) -> u64 {
        if self.base_delay_ms == 0 || self.max_delay_ms == 0 {
            return 0;
        }

        if retry_number >= u64::BITS {
            return self.max_delay_ms;
        }

        let multiplier_shift = retry_number as u32;
        if self.base_delay_ms > (self.max_delay_ms >> multiplier_shift) {
            self.max_delay_ms
        } else {
            self.base_delay_ms << multiplier_shift
        }
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    #[test]
    fn delay_saturates_without_overflow() {
        let config = RetryConfig {
            max_attempts: u32::MAX,
            base_delay_ms: u64::MAX,
            max_delay_ms: 123,
        };
        assert_eq!(config.delay_for_retry(u32::MAX), 123);
    }

    #[test]
    fn delay_grows_until_cap() {
        let config = RetryConfig {
            max_attempts: 5,
            base_delay_ms: 10,
            max_delay_ms: 25,
        };
        assert_eq!(config.delay_for_retry(0), 10);
        assert_eq!(config.delay_for_retry(1), 20);
        assert_eq!(config.delay_for_retry(2), 25);
    }

    #[test]
    fn zero_base_delay_stays_zero_at_large_retry_numbers() {
        let config = RetryConfig {
            max_attempts: u32::MAX,
            base_delay_ms: 0,
            max_delay_ms: u64::MAX,
        };
        assert_eq!(config.delay_for_retry(u32::MAX), 0);
    }
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    if config.max_attempts == 0 {
        return Err(RetryError::Permanent(
            "max_attempts must be at least 1".into(),
        ));
    }

    for attempt in 0..config.max_attempts {
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if error.is_transient() && attempt + 1 < config.max_attempts => {
                sleeper.sleep_ms(config.delay_for_retry(attempt));
            }
            Err(error) => return Err(error),
        }
    }

    unreachable!("max_attempts is checked above");
}

#[cfg(test)]
mod tests {
    use super::*;

    fn config(max_attempts: u32) -> RetryConfig {
        RetryConfig {
            max_attempts,
            base_delay_ms: 10,
            max_delay_ms: 25,
        }
    }

    #[test]
    fn retries_transient_errors_with_bounded_delays() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(5), &mut sleeper, || {
            calls += 1;
            if calls < 4 {
                Err(RetryError::Transient("temporary".into()))
            } else {
                Ok(())
            }
        });
        assert_eq!(result, Ok(()));
        assert_eq!(calls, 4);
        assert_eq!(sleeper.sleeps, vec![10, 20, 25]);
    }

    #[test]
    fn permanent_errors_return_without_retrying() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(5), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("invalid".into()))
        });
        assert_eq!(result, Err(RetryError::Permanent("invalid".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn attempt_budget_includes_first_call() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(3), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("temporary".into()))
        });
        assert_eq!(result, Err(RetryError::Transient("temporary".into())));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![10, 20]);
    }
}

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn public_delay_contract_saturates_for_large_retry_numbers() {
    let config = RetryConfig {
        max_attempts: u32::MAX,
        base_delay_ms: u64::MAX,
        max_delay_ms: 123,
    };

    assert_eq!(config.delay_for_retry(u32::MAX), 123);
}

#[test]
fn public_run_job_retries_transient_errors_only() {
    let config = RetryConfig {
        max_attempts: 2,
        base_delay_ms: 5,
        max_delay_ms: 5,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("temporary".into()))
    });

    assert_eq!(result, Err(RetryError::Transient("temporary".into())));
    assert_eq!(calls, 2);
    assert_eq!(sleeper.sleeps, vec![5]);
}

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

fn config(max_attempts: u32) -> RetryConfig {
    RetryConfig {
        max_attempts,
        base_delay_ms: 10,
        max_delay_ms: 25,
    }
}

#[test]
fn public_api_retries_transient_failures_and_caps_delay() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config(5), &mut sleeper, || {
        calls += 1;
        if calls == 4 {
            Ok(())
        } else {
            Err(RetryError::Transient("temporary".into()))
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 4);
    assert_eq!(sleeper.sleeps, vec![10, 20, 25]);
}

#[test]
fn public_api_does_not_retry_permanent_failures() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config(4), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Permanent("invalid input".into()))
    });

    assert_eq!(result, Err(RetryError::Permanent("invalid input".into())));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn zero_attempts_is_rejected_without_calling_job() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(
        &RetryConfig {
            max_attempts: 0,
            base_delay_ms: 10,
            max_delay_ms: 25,
        },
        &mut sleeper,
        || {
            calls += 1;
            Ok(())
        },
    );

    assert_eq!(calls, 0);
    assert_eq!(
        result,
        Err(RetryError::Permanent(
            "max_attempts must be at least 1".into()
        ))
    );
}
